from pathlib import Path

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from scipy.interpolate import interp1d
from scipy.stats import linregress, norm

ROOT = Path(__file__).resolve().parent
DATA_FILE = ROOT / "data" / "quarterly_data.csv"
RESULTS_DIR = ROOT / "results"

# Campbell and Cochrane's reported annualized calibration.
MU_C_ANNUAL = 0.0189
SIGMA_C_ANNUAL = 0.0150
PHI_ANNUAL = 0.87
GAMMA = 2.0
RF_ANNUAL = 0.0094


def calibrate() -> dict[str, float]:
    """Convert the annual calibration to quarterly frequency and compute B1."""
    mu_c = MU_C_ANNUAL / 4
    sigma_c = SIGMA_C_ANNUAL / np.sqrt(4)
    phi = PHI_ANNUAL ** (1 / 4)
    rf = RF_ANNUAL / 4

    # A2(a): rf = -log(delta) + gamma*mu_c - gamma*(1-phi)/2.
    delta = np.exp(GAMMA * mu_c - 1 / 2 * GAMMA * (1 - phi) - rf)

    # Campbell--Cochrane steady-state surplus-consumption ratio and its ceiling.
    s_bar_ratio = sigma_c * np.sqrt(GAMMA / (1 - phi))
    s_bar = np.log(s_bar_ratio)
    s_max = s_bar + 0.5 * (1 - s_bar_ratio**2)
    s_max_ratio = np.exp(s_max)

    data = pd.read_csv(DATA_FILE)
    growth = data["consumption_growth"].dropna()
    sample_mean = growth.mean()
    sample_std = growth.std(ddof=1)

    return {
        "mu_c": mu_c,
        "sigma_c": sigma_c,
        "phi": phi,
        "gamma": GAMMA,
        "rf": rf,
        "delta": delta,
        "S_bar": s_bar_ratio,
        "S_max": s_max_ratio,
        "s_bar": s_bar,
        "s_max": s_max,
        "sample_mean": sample_mean,
        "sample_std": sample_std,
        "sample_n": len(growth),
    }


def build_surplus_grid(s_max_ratio: float) -> np.ndarray:
    """Construct Wachter's (2005) third grid for log surplus consumption."""
    # 101 positive S points: include S_max and exclude zero.
    surplus_segment = np.linspace(0.0, s_max_ratio, 102)[1:]
    log_surplus_segment = np.log(surplus_segment)

    # 900 s points: include -300 and exclude the first point above.
    lower_segment = np.linspace(-300.0, log_surplus_segment[0], 901)[:-1]
    return np.concatenate((lower_segment, log_surplus_segment))


def sensitivity(s: np.ndarray, values: dict[str, float]) -> np.ndarray:
    """Campbell--Cochrane sensitivity function lambda(s)."""
    inside = np.maximum(1.0 - 2.0 * (s - values["s_bar"]), 0.0)
    return np.where(
        s <= values["s_max"],
        np.sqrt(inside) / values["S_bar"] - 1.0,
        0.0,
    )


def prepare_strip_terms(
    grid: np.ndarray, values: dict[str, float], quadrature_order: int = 80
) -> dict[str, np.ndarray]:
    """Precompute terms shared by every step of the strip recursion."""
    nodes, weights = np.polynomial.legendre.leggauss(quadrature_order)
    epsilon = 12.0 * values["sigma_c"] * nodes
    integration_weights = (
        12.0
        * values["sigma_c"]
        * weights
        * norm.pdf(epsilon, loc=0.0, scale=values["sigma_c"])
    )
    lam = sensitivity(grid, values)
    next_s = (
        (1.0 - values["phi"]) * values["s_bar"]
        + values["phi"] * grid[:, None]
        + lam[:, None] * epsilon[None, :]
    )
    loading = 1.0 - values["gamma"] * (1.0 + lam)
    common = values["delta"] * np.exp(
        (1.0 - values["gamma"]) * values["mu_c"]
        - values["gamma"] * (1.0 - values["phi"]) * (values["s_bar"] - grid)
    )
    return {
        "next_s": next_s,
        "exponential_term": np.exp(loading[:, None] * epsilon[None, :]),
        "integration_weights": integration_weights,
        "common": common,
        "loading": loading,
    }


def log_linear_interpolator(grid: np.ndarray, strip: np.ndarray):
    """Return a positive log-linear interpolator with linear extrapolation."""
    log_interpolator = interp1d(
        grid,
        np.log(strip),
        kind="linear",
        bounds_error=False,
        fill_value="extrapolate",
        assume_sorted=True,
    )

    def interpolate(s: np.ndarray) -> np.ndarray:
        return np.exp(log_interpolator(s))

    return interpolate


def next_strip(
    grid: np.ndarray,
    previous_strip: np.ndarray,
    values: dict[str, float],
    terms: dict[str, np.ndarray] | None = None,
) -> np.ndarray:
    """Compute F_n on the grid from the vector F_{n-1}."""
    if terms is None:
        terms = prepare_strip_terms(grid, values)
    interpolate_previous = log_linear_interpolator(grid, previous_strip)
    return terms["common"] * np.sum(
        terms["exponential_term"]
        * interpolate_previous(terms["next_s"])
        * terms["integration_weights"][None, :],
        axis=1,
    )


def analytical_first_strip(
    grid: np.ndarray,
    values: dict[str, float],
    terms: dict[str, np.ndarray] | None = None,
) -> np.ndarray:
    """Evaluate the closed-form expression for F1 from A1(b)."""
    if terms is None:
        terms = prepare_strip_terms(grid, values)
    return terms["common"] * np.exp(
        0.5 * terms["loading"] ** 2 * values["sigma_c"] ** 2
    )


def consumption_claim(
    grid: np.ndarray,
    values: dict[str, float],
    tolerance: float = 1e-10,
    quadrature_order: int = 80,
    max_horizon: int = 10_000,
) -> tuple[np.ndarray, int, object]:
    """Recursively sum consumption strips until the pointwise stopping rule."""
    terms = prepare_strip_terms(grid, values, quadrature_order)
    previous_strip = np.ones_like(grid)
    price_dividend_ratio = np.zeros_like(grid)

    for horizon in range(1, max_horizon + 1):
        current_strip = next_strip(grid, previous_strip, values, terms)
        price_dividend_ratio += current_strip

        if np.all(current_strip < tolerance * price_dividend_ratio):
            return (
                price_dividend_ratio,
                horizon,
                log_linear_interpolator(grid, price_dividend_ratio),
            )
        previous_strip = current_strip

    raise RuntimeError(
        f"Consumption-strip recursion did not converge by n={max_horizon}."
    )


def simulate_model(
    values: dict[str, float],
    interpolate_g,
    periods: int = 50_000,
    seed: int = 12345,
    quadrature_order: int = 80,
    batch_size: int = 5_000,
) -> dict[str, np.ndarray]:
    """Simulate states and compute realized and conditional asset-pricing objects."""
    rng = np.random.default_rng(seed)
    shocks = rng.normal(0.0, values["sigma_c"], periods)

    states = np.empty(periods + 1)
    states[0] = values["s_bar"]
    for t in range(periods):
        lam = sensitivity(np.array([states[t]]), values)[0]
        states[t + 1] = (
            (1.0 - values["phi"]) * values["s_bar"]
            + values["phi"] * states[t]
            + lam * shocks[t]
        )

    current_s = states[:-1]
    next_s_realized = states[1:]
    price_dividend_ratio = interpolate_g(current_s)
    next_price_dividend_ratio = interpolate_g(next_s_realized)

    log_sdf = (
        np.log(values["delta"])
        - values["gamma"] * (next_s_realized - current_s)
        - values["gamma"] * (values["mu_c"] + shocks)
    )
    sdf = np.exp(log_sdf)
    realized_log_return = (
        np.log1p(next_price_dividend_ratio)
        - np.log(price_dividend_ratio)
        + values["mu_c"]
        + shocks
    )

    nodes, weights = np.polynomial.legendre.leggauss(quadrature_order)
    epsilon = 12.0 * values["sigma_c"] * nodes
    integration_weights = (
        12.0
        * values["sigma_c"]
        * weights
        * norm.pdf(epsilon, loc=0.0, scale=values["sigma_c"])
    )
    expected_return = np.empty(periods)
    risk_free_gross = np.empty(periods)

    for start in range(0, periods, batch_size):
        stop = min(start + batch_size, periods)
        s_batch = current_s[start:stop]
        g_batch = price_dividend_ratio[start:stop]
        lam = sensitivity(s_batch, values)
        next_s = (
            (1.0 - values["phi"]) * values["s_bar"]
            + values["phi"] * s_batch[:, None]
            + lam[:, None] * epsilon[None, :]
        )
        next_g = interpolate_g(next_s)
        gross_return = (
            (1.0 + next_g)
            / g_batch[:, None]
            * np.exp(values["mu_c"] + epsilon)[None, :]
        )
        conditional_sdf = values["delta"] * np.exp(
            -values["gamma"] * (next_s - s_batch[:, None])
            - values["gamma"] * (values["mu_c"] + epsilon)[None, :]
        )
        expected_return[start:stop] = np.sum(
            gross_return * integration_weights[None, :], axis=1
        )
        risk_free_gross[start:stop] = 1.0 / np.sum(
            conditional_sdf * integration_weights[None, :], axis=1
        )

    return {
        "state": current_s,
        "shock": shocks,
        "consumption_growth": values["mu_c"] + shocks,
        "price_dividend_ratio": price_dividend_ratio,
        "sdf": sdf,
        "equity_risk_premium": expected_return - risk_free_gross,
        "risk_free_rate": risk_free_gross - 1.0,
        "log_risk_free_rate": np.log(risk_free_gross),
        "realized_log_return": realized_log_return,
    }


def sample_moments(simulation: dict[str, np.ndarray]) -> dict[str, float]:
    """Compute the annualized B5 sample moments from quarterly observations."""
    consumption_growth = simulation["consumption_growth"]
    log_excess_return = (
        simulation["realized_log_return"] - simulation["log_risk_free_rate"]
    )
    annual_excess_mean = 4.0 * log_excess_return.mean()
    annual_excess_std = 2.0 * log_excess_return.std(ddof=1)
    risk_premium = annual_excess_mean + 0.5 * annual_excess_std**2

    log_price_dividend = np.log(simulation["price_dividend_ratio"] / 4.0)
    annual_autocorrelation = np.corrcoef(
        log_price_dividend[4:], log_price_dividend[:-4]
    )[0, 1]

    return {
        "consumption_growth_mean": 4.0 * consumption_growth.mean(),
        "consumption_growth_std": 2.0 * consumption_growth.std(ddof=1),
        "risk_free_rate_mean": 4.0 * simulation["log_risk_free_rate"].mean(),
        "log_excess_return_mean": annual_excess_mean,
        "log_excess_return_std": annual_excess_std,
        "risk_premium": risk_premium,
        "sharpe_ratio": risk_premium / annual_excess_std,
        "mean_price_dividend_ratio": np.exp(log_price_dividend.mean()),
        "log_price_dividend_std": log_price_dividend.std(ddof=1),
        "log_price_dividend_autocorrelation": annual_autocorrelation,
        "sdf_ratio": 2.0 * simulation["sdf"].std(ddof=1)
        / simulation["sdf"].mean(),
    }


def predictive_regression(simulation: dict[str, np.ndarray]) -> dict[str, float]:
    """Regress annual log excess returns on lagged log price-dividend ratios."""
    quarterly_excess_return = (
        simulation["realized_log_return"] - simulation["log_risk_free_rate"]
    )
    number_of_years = len(quarterly_excess_return) // 4
    annual_excess_return = quarterly_excess_return[
        : 4 * number_of_years
    ].reshape(number_of_years, 4).sum(axis=1)

    # Quarter 4k is the preceding year-end for returns in quarters 4k,...,4k+3.
    lagged_log_price_dividend = np.log(
        simulation["price_dividend_ratio"][0 : 4 * number_of_years : 4] / 4.0
    )
    regression = linregress(lagged_log_price_dividend, annual_excess_return)
    return {
        "slope": regression.slope,
        "t_statistic": regression.slope / regression.stderr,
        "r_squared": regression.rvalue**2,
        "observations": number_of_years,
    }


def write_latex(values: dict[str, float]) -> None:
    """Write the computed B1 tables included by the main LaTeX document."""
    RESULTS_DIR.mkdir(exist_ok=True)
    rows = [
        (r"$\bar S$", values["S_bar"]),
        (r"$S_{\max}$", values["S_max"]),
    ]
    lines = [
        r"\begin{tabular}{lr}",
        r"\toprule",
        r"Parameter & Quarterly value \\",
        r"\midrule",
    ]
    for label, value in rows:
        display = (
            f"{100 * value:.4f}\\%"
            if label
            in {r"$\mu_c^Q$", r"$\sigma_c^Q$", r"$r_f^Q$", r"$\bar S$", r"$S_{\max}$"}
            else f"{value:.6f}"
        )
        lines.append(f"{label} & {display} " + r"\\")
    lines.extend([r"\bottomrule", r"\end{tabular}"])
    (RESULTS_DIR / "b1_calibration.tex").write_text("\n".join(lines) + "\n")

    comparison_lines = [
        r"\begin{tabular}{lrr}",
        r"\toprule",
        r"Quarterly moment & Calibration & Data \\",
        r"\midrule",
        rf"$\mu_c$ & "
        f"{100 * values['mu_c']:.4f}\\% & {100 * values['sample_mean']:.4f}\\% "
        + r"\\",
        rf"$\sigma_c$ & "
        f"{100 * values['sigma_c']:.4f}\\% & {100 * values['sample_std']:.4f}\\% "
        + r"\\",
        r"\bottomrule",
        r"\end{tabular}",
    ]
    (RESULTS_DIR / "b1_consumption_comparison.tex").write_text(
        "\n".join(comparison_lines) + "\n"
    )


def write_sample_moments_latex(moments: dict[str, float]) -> None:
    """Write the annualized B5 sample moments table."""
    rows = [
        (r"$E[\Delta c]$ (\%)", "consumption_growth_mean", 100.0),
        (r"$\sigma(\Delta c)$ (\%)", "consumption_growth_std", 100.0),
        (r"$E[r_f]$ (\%)", "risk_free_rate_mean", 100.0),
        (r"$E[r-r_f]$ (\%)", "log_excess_return_mean", 100.0),
        (r"$\sigma(r-r_f)$ (\%)", "log_excess_return_std", 100.0),
        (r"Risk premium (\%)", "risk_premium", 100.0),
        (r"Sharpe ratio", "sharpe_ratio", 1.0),
        (r"$\exp(E[p-d])$", "mean_price_dividend_ratio", 1.0),
        (r"$\sigma(p-d)$", "log_price_dividend_std", 1.0),
        (
            r"Annual autocorrelation of $p-d$",
            "log_price_dividend_autocorrelation",
            1.0,
        ),
        (r"$\sigma(M)/E[M]$", "sdf_ratio", 1.0),
    ]
    lines = [
        r"\begin{tabular}{lr}",
        r"\toprule",
        r"Moment & Value \\",
        r"\midrule",
    ]
    for label, key, scale in rows:
        lines.append(f"{label} & {scale * moments[key]:.4f} " + r"\\")
    lines.extend([r"\bottomrule", r"\end{tabular}"])
    (RESULTS_DIR / "b5_sample_moments.tex").write_text(
        "\n".join(lines) + "\n"
    )


def write_predictive_regression_latex(regression: dict[str, float]) -> None:
    """Write the B5(f) predictive-regression results."""
    lines = [
        r"\begin{tabular}{lr}",
        r"\toprule",
        r"Statistic & Value \\",
        r"\midrule",
        rf"Slope & {regression['slope']:.4f} \\",
        rf"$t$-statistic & {regression['t_statistic']:.4f} \\",
        rf"$R^2$ & {regression['r_squared']:.4f} \\",
        rf"Observations & {int(regression['observations'])} \\",
        r"\bottomrule",
        r"\end{tabular}",
    ]
    (RESULTS_DIR / "b5f_predictive_regression.tex").write_text(
        "\n".join(lines) + "\n"
    )


def plot_first_strip(
    grid: np.ndarray, numerical: np.ndarray, analytical: np.ndarray
) -> None:
    """Plot numerical and analytical values of the first consumption strip."""
    figure, axis = plt.subplots(figsize=(7.5, 4.5))
    axis.plot(grid, numerical, linewidth=2.0, label="Numerical integration")
    axis.plot(
        grid,
        analytical,
        linestyle="--",
        linewidth=1.6,
        label="Analytical expression",
    )
    axis.set_xscale("symlog", linthresh=1.0)
    axis.set_xticks([-100, -10])
    axis.set_xticklabels(["-100", "-10"])
    axis.set_xlabel(r"$s_t$")
    axis.set_ylabel(r"$F_1(s_t)$")
    axis.set_title("First consumption strip")
    axis.legend()
    axis.grid(alpha=0.25)
    figure.tight_layout()
    figure.savefig(RESULTS_DIR / "b3_first_strip.pdf")
    plt.close(figure)


def plot_price_dividend_ratio(grid: np.ndarray, ratio: np.ndarray) -> None:
    """Plot the converged price-dividend ratio G(s)."""
    figure, axis = plt.subplots(figsize=(7.5, 4.5))
    axis.plot(grid, ratio, linewidth=2.0)
    axis.set_xscale("symlog", linthresh=1.0)
    axis.set_xticks([-100, -10])
    axis.set_xticklabels(["-100", "-10"])
    axis.set_xlabel(r"$s$")
    axis.set_ylabel(r"$G(s)$")
    axis.set_title("Price-dividend ratio")
    axis.grid(alpha=0.25)
    figure.tight_layout()
    figure.savefig(RESULTS_DIR / "b4_price_dividend_ratio.pdf")
    plt.close(figure)


def plot_simulation(simulation: dict[str, np.ndarray]) -> None:
    """Plot the B5 quantities as functions of the simulated state s_t."""
    state = simulation["state"]
    order = np.argsort(state)
    panels = [
        ("price_dividend_ratio", r"$G(s_t)$", 1.0, False),
        ("sdf", r"$M_{t+1}$", 1.0, True),
        ("equity_risk_premium", "Equity risk premium (%)", 100.0, False),
        ("risk_free_rate", "Risk-free rate (%)", 100.0, False),
        ("realized_log_return", r"$r_{t+1}$ (%)", 100.0, True),
    ]
    figure, axes = plt.subplots(
        len(panels), 1, figsize=(9.0, 10.0), sharex=True, constrained_layout=True
    )
    for axis, (key, label, scale, realized) in zip(axes, panels):
        if realized:
            axis.scatter(
                state,
                scale * simulation[key],
                s=1.0,
                alpha=0.15,
                rasterized=True,
            )
        else:
            axis.plot(
                state[order],
                scale * simulation[key][order],
                linewidth=1.2,
                rasterized=True,
            )
        axis.set_ylabel(label)
        axis.grid(alpha=0.2)
    axes[-1].set_xlabel(r"$s_t$")
    figure.suptitle(r"Asset-pricing quantities as functions of $s_t$")
    figure.savefig(RESULTS_DIR / "b5_simulated_quantities.pdf", dpi=200)
    plt.close(figure)


def plot_surplus_consumption_ratio(simulation: dict[str, np.ndarray]) -> None:
    """Plot the simulated surplus-consumption ratio S_t over time."""
    quarters = np.arange(len(simulation["state"]))
    surplus_ratio = 100.0 * np.exp(simulation["state"])
    figure, axis = plt.subplots(figsize=(9.0, 4.5))
    axis.plot(quarters, surplus_ratio, linewidth=0.5, rasterized=True)
    axis.set_xlabel("Quarter")
    axis.set_ylabel(r"$S_t$ (\%)")
    axis.set_title("Simulated surplus-consumption ratio")
    axis.grid(alpha=0.2)
    figure.tight_layout()
    figure.savefig(RESULTS_DIR / "b5_surplus_consumption_ratio.pdf", dpi=200)
    plt.close(figure)


def risk_free_rate_on_grid(
    grid: np.ndarray,
    values: dict[str, float],
) -> np.ndarray:
    """Return the constant conditional net risk-free rate from A2(a)."""
    return np.full_like(grid, np.expm1(values["rf"]))


def plot_risk_free_and_price_dividend(
    grid: np.ndarray,
    price_dividend_ratio: np.ndarray,
    risk_free_rate: np.ndarray,
) -> None:
    """Plot R_f(s_t) and G(s_t) against the log surplus-consumption ratio."""
    figure, axes = plt.subplots(
        2, 1, figsize=(7.5, 7.0), sharex=True, constrained_layout=True
    )
    axes[0].plot(grid, 100.0 * risk_free_rate, linewidth=2.0)
    axes[0].set_ylabel(r"$R_f(s_t)-1$ (\%)")
    axes[0].set_title("Risk-free rate")
    axes[1].plot(grid, price_dividend_ratio, linewidth=2.0)
    axes[1].set_ylabel(r"$G(s_t)$")
    axes[1].set_title("Price-dividend ratio")
    axes[1].set_xlabel(r"$s_t$")
    for axis in axes:
        axis.set_xscale("symlog", linthresh=1.0)
        axis.set_xticks([-100, -10])
        axis.set_xticklabels(["-100", "-10"])
        axis.grid(alpha=0.25)
    figure.savefig(RESULTS_DIR / "b5e_rf_price_dividend.pdf")
    plt.close(figure)


if __name__ == "__main__":
    results = calibrate()
    grid = build_surplus_grid(s_max_ratio=results["S_max"])
    strip_terms = prepare_strip_terms(grid, results)
    numerical_f1 = next_strip(grid, np.ones_like(grid), results, strip_terms)
    closed_form_f1 = analytical_first_strip(grid, results, strip_terms)
    if not np.allclose(numerical_f1, closed_form_f1, rtol=1e-8, atol=1e-8):
        raise RuntimeError("Numerical F1 does not match its closed form.")
    write_latex(results)
    plot_first_strip(grid, numerical_f1, closed_form_f1)
    price_dividend_ratio, final_horizon, interpolate_g = consumption_claim(
        grid, results
    )
    plot_price_dividend_ratio(grid, price_dividend_ratio)
    grid_risk_free_rate = risk_free_rate_on_grid(grid, results)
    plot_risk_free_and_price_dividend(
        grid, price_dividend_ratio, grid_risk_free_rate
    )
    simulation = simulate_model(results, interpolate_g)
    moments = sample_moments(simulation)
    regression = predictive_regression(simulation)
    write_sample_moments_latex(moments)
    write_predictive_regression_latex(regression)
    plot_surplus_consumption_ratio(simulation)
    plot_simulation(simulation)
    for key, value in results.items():
        print(f"{key}: {value}")
